%[text] # Test time report
%[text] Select a test result XML file which the Build Tool generated.
% test_result_file = SearchUtil1.searchFiles("sample-test-result.xml");
test_result_file = "C:\local\modutil\modeling-utility\Devel\TestUtil\Test\summarizeTestResult\sample-test-result.xml"; %[control:filebrowser:4366]{"position":[20,118]}
disp(test_result_file) %[output:9f7b2c3d]
assert(not(isempty(test_result_file)))
test_result_file = test_result_file(1);
%%
test_summary = TestUtil1.summarizeTestResult(test_result_file);
disp("Number of tests: " + test_summary.Properties.CustomProperties.NumTests) %[output:20b4f152]
disp("Total test time (seconds): " + test_summary.Properties.CustomProperties.TotalTestTime) %[output:4010eae6]
disp("Median test time (seconds): " + test_summary.Properties.CustomProperties.MedianTestTime) %[output:9d458a25]
disp(head(test_summary)) %[output:16e4bd4a]
threshold = 20;

test_fullname = test_summary.TestClass + " > " + test_summary.TestFunction;
testname = test_fullname(1:threshold);
testname = flip(testname);

testtime = test_summary.TestTime;
testtime = flip(testtime(1:threshold));

fig = figure; %[output:1a76689f]
fig.Position(3) = 700;  % width %[output:1a76689f]
fig.Position(4) = 500;  % height %[output:1a76689f]
ax = axes(fig); %[output:1a76689f]
ax.TickLabelInterpreter = "none"; %[output:1a76689f]
ax.FontName = "FixedWidth"; %[output:1a76689f]
hold(ax, "on") %[output:1a76689f]
grid(ax, "on") %[output:1a76689f]
b = barh(ax, testname, testtime); %[output:1a76689f]
title(ax, "Test time top " + threshold) %[output:1a76689f]
xlabel(ax, "seconds") %[output:1a76689f]
